cd /app && python3 << 'EOF'
import hashlib

# Read the image file
with open('/app/code.png', 'rb') as f:
    img_bytes = f.read()

SALT = b"0000TBENCH-SALT"

# Try all major hash algorithms to see which produces bee26a prefix
algorithms = ['md5', 'sha1', 'sha224', 'sha256', 'sha384', 'sha512', 'blake2b', 'blake2s']

h0_sha256 = hashlib.sha256(img_bytes).hexdigest()

for algo in algorithms:
    try:
        if algo == 'blake2b':
            H = hashlib.blake2b(h0_sha256[:10].encode() + SALT).hexdigest()
        elif algo == 'blake2s':
            H = hashlib.blake2s(h0_sha256[:10].encode() + SALT).hexdigest()
        else:
            hasher = hashlib.new(algo)
            hasher.update(h0_sha256[:10].encode() + SALT)
            H = hasher.hexdigest()

        if H.startswith('bee26a'):
            print(f"FOUND! {algo}: {H}")
        else:
            print(f"{algo}: {H[:20]}...")
    except Exception as e:
        print(f"{algo}: Error - {e}")
EOF
